import React, { useState } from "react";
import Home from "./pages/Home";
import AdminLogin from "./pages/AdminLogin";
import AdminPanel from "./pages/AdminPanel";
import UserLogin from "./pages/UserLogin";
import UserPanel from "./pages/UserPanel";

function App() {
  const [view, setView] = useState("home");
  const [adminToken, setAdminToken] = useState("");
  const [userToken, setUserToken] = useState("");

  return (
    <div>
      <header style={{ padding: 20, background: "#eee" }}>
        <button onClick={() => setView("home")}>Home</button>
        <button onClick={() => setView("adminLogin")}>Admin Login</button>
        <button onClick={() => setView("userLogin")}>User Login</button>
      </header>

      <main>
        {view === "home" && <Home />}
        {view === "adminLogin" && (
          <AdminLogin
            setAdminToken={setAdminToken}
            setView={setView}
          />
        )}
        {view === "adminPanel" && <AdminPanel token={adminToken} />}
        {view === "userLogin" && (
          <UserLogin
            setUserToken={setUserToken}
            setView={setView}
          />
        )}
        {view === "userPanel" && <UserPanel token={userToken} />}
      </main>
    </div>
  );
}

export default App;
